    this.refill = refill
    this.per = per
    this.byKey = new Map()
  }

  advance(key, tick) {
    let s = this.byKey.get(key)
    if (!s) {
      // Starts full when the key first reaches it.
      s = { tokensNum: this.capacity * this.per, lastTick: tick }
      this.byKey.set(key, s)
      return
    }
